#!/bin/bash
set -eo pipefail

# Parse flags
BENCHMARK_MODE=false
for arg in "$@"; do
    case "$arg" in
        --benchmark) BENCHMARK_MODE=true ;;
    esac
done

# Cloud-Linux dev envs set CONDUCTOR_* via .cloud-env (generated by
# scripts/cloud-build.sh during Cord's build phase). When .cloud-env exists,
# it is authoritative — always source it so the cloud-generated workspace
# name cannot be overridden by stale env vars or command-line params.
SCRIPT_SOURCE="${BASH_SOURCE[0]:-$0}"
SCRIPT_DIR="$(cd "$(dirname "$SCRIPT_SOURCE")" && pwd)"
if [ -f "$SCRIPT_DIR/../.cloud-env" ]; then
    . "$SCRIPT_DIR/../.cloud-env"
elif [ -z "${CONDUCTOR_PORT:-}" ]; then
    echo '❌ CONDUCTOR_PORT not set. Run via Conductor, or run scripts/cloud-build.sh first on cloud envs.'
    exit 1
fi

. "$SCRIPT_DIR/lib/workspace-env.sh"
normalize_conductor_workspace_env
. "$SCRIPT_DIR/lib/run-process-cleanup.sh"

# mac-app is Electron + requires nvm/Node 20.10.0; only runs on macOS.
IS_MAC=false
[ "$(uname)" = "Darwin" ] && IS_MAC=true

# Assign ports from a base port. Uses offsets 0-5 (5 services + 1 DB).
# Research was retired post-rose-migration so no research ports are reserved.
assign_ports() {
    local base=$1
    export BACKEND_PORT=$base
    export FRONTEND_PORT=$((base + 1))
    export HEALTH_PORT=$((base + 2))
    export MAC_APP_PORT=$((base + 3))
    export SDK_METRICS_PORT=$((base + 4))
    export LOCAL_DB_PORT=$((base + 5))
    export NGROK_WEB_PORT=$((base + 9))
    export BACKEND_API_URL=http://localhost:$BACKEND_PORT
    export VITE_BACKEND_API_URL=http://localhost:$BACKEND_PORT
    export BACKEND_URL=http://localhost:$BACKEND_PORT
    export ALLOWED_ORIGINS=http://localhost:$FRONTEND_PORT,http://localhost:$MAC_APP_PORT
}

docker_ps_ports_quick() {
    local tmp pid status
    tmp=$(mktemp)
    docker ps --format "$1" >"$tmp" 2>/dev/null &
    pid=$!
    for _ in 1 2 3 4 5; do
        if ! kill -0 "$pid" 2>/dev/null; then
            status=0
            wait "$pid" || status=$?
            cat "$tmp"
            rm -f "$tmp"
            return $status
        fi
        sleep 0.2
    done
    kill -9 "$pid" 2>/dev/null || true
    wait "$pid" 2>/dev/null || true
    rm -f "$tmp"
    return 1
}

docker_info_quick() {
    local pid status
    docker info >/dev/null 2>&1 &
    pid=$!
    for _ in 1 2 3 4 5; do
        if ! kill -0 "$pid" 2>/dev/null; then
            status=0
            wait "$pid" || status=$?
            return $status
        fi
        sleep 0.2
    done
    kill -9 "$pid" 2>/dev/null || true
    wait "$pid" 2>/dev/null || true
    return 1
}

# Check cwd first because many service command lines are just "node" or
# "python3" and do not include the worktree path.
process_belongs_to_this_worktree() {
    local pid=$1
    local cwd cmd
    cwd=$(lsof -a -p "$pid" -d cwd -Fn 2>/dev/null | sed -n 's/^n//p' | head -1) || true
    if [ "$cwd" = "$PWD" ] || [[ "$cwd" == "$PWD"/* ]]; then
        return 0
    fi
    cmd=$(ps -p "$pid" -o command= 2>/dev/null) || true
    echo "$cmd" | grep -Fq "$PWD"
}

# Check if a port requires moving this workspace to a different range.
# Current-worktree processes are handled later as stale/running services; any
# other listener should trigger reassignment before services or Postgres start.
port_requires_reassign() {
    local port=$1
    local pids
    pids=$(lsof -ti :"$port" 2>/dev/null) || true
    for pid in $pids; do
        local cmd
        cmd=$(ps -p "$pid" -o command= 2>/dev/null) || true
        # Docker daemon is a single process for all containers — check containers separately below
        echo "$cmd" | grep -qi docker && continue
        if ! process_belongs_to_this_worktree "$pid"; then
            return 0  # another process already owns this port
        fi
    done

    # Check if a Docker container from another workspace maps to this port.
    local docker_ports name ports
    docker_ports=$(docker_ps_ports_quick '{{.Names}}\t{{.Ports}}' | grep ":${port}->" || true)
    while IFS=$'\t' read -r name ports; do
        [ -z "$name" ] && continue
        if [ -n "${CONDUCTOR_WORKSPACE_NAME:-}" ] && echo "$name" | grep -Fq "$CONDUCTOR_WORKSPACE_NAME"; then
            continue
        fi
        return 0
    done <<< "$docker_ports"

    return 1
}

port_is_free_for_candidate_range() {
    local port=$1
    if lsof -ti :"$port" >/dev/null 2>&1; then
        return 1
    fi
    if docker_ps_ports_quick '{{.Ports}}' | grep -q ":${port}->"; then
        return 1
    fi
    return 0
}

if [ "${RUN_SH_SOURCE_ONLY:-false}" = "true" ]; then
    return 0 2>/dev/null || exit 0
fi

# Try the Conductor-assigned port first
assign_ports "$CONDUCTOR_PORT"

# If any port in our range is held by another process, find a safe range
COLLISION=false
for port in $BACKEND_PORT $FRONTEND_PORT $HEALTH_PORT $MAC_APP_PORT $SDK_METRICS_PORT $LOCAL_DB_PORT $NGROK_WEB_PORT; do
    if port_requires_reassign "$port"; then
        COLLISION=true
        break
    fi
done

if $COLLISION; then
    echo "⚠️  Port range $CONDUCTOR_PORT is already occupied — scanning for free range..."
    # Scan upward in steps of 20 from the assigned port
    CANDIDATE=$((CONDUCTOR_PORT + 20))
    FOUND=false
    while [ $CANDIDATE -lt 65500 ]; do
        RANGE_FREE=true
        for offset in 0 1 2 3 4 5 9; do
            p=$((CANDIDATE + offset))
            if ! port_is_free_for_candidate_range "$p"; then
                RANGE_FREE=false
                break
            fi
        done
        if $RANGE_FREE; then
            FOUND=true
            break
        fi
        CANDIDATE=$((CANDIDATE + 20))
    done
    if ! $FOUND; then
        echo "❌ Could not find a free port range. All ranges 55000-65500 occupied."
        exit 1
    fi
    assign_ports "$CANDIDATE"
    echo "✅ Reassigned to port range $CANDIDATE"
fi

IS_CLOUD=false
[ -f "$SCRIPT_DIR/../.cloud-env" ] && IS_CLOUD=true

if ! $IS_CLOUD; then
    export MAX_CONCURRENT_ACTIVITIES="${MAX_CONCURRENT_ACTIVITIES:-500}"
    export MAX_CONCURRENT_ACTIVITY_TASK_POLLERS="${MAX_CONCURRENT_ACTIVITY_TASK_POLLERS:-80}"
fi

export NODE_ENV="${NODE_ENV:-development}"
export TEMPORAL_TASK_QUEUE=navi-agent-tasks-$CONDUCTOR_WORKSPACE_NAME
echo "🔌 Ports: backend=$BACKEND_PORT frontend=$FRONTEND_PORT health=$HEALTH_PORT mac-app=$MAC_APP_PORT metrics=$SDK_METRICS_PORT db=$LOCAL_DB_PORT ngrok_api=$NGROK_WEB_PORT queue=$TEMPORAL_TASK_QUEUE benchmark_mode=$BENCHMARK_MODE activity_max_slots=${MAX_CONCURRENT_ACTIVITIES:-100} activity_pollers=${MAX_CONCURRENT_ACTIVITY_TASK_POLLERS:-8}"

run_kill_stale_same_task_queue_workers "$PWD" "$TEMPORAL_TASK_QUEUE" "$BACKEND_API_URL" "$$"

is_current_process_family() {
    local pid=$1
    while [ -n "$pid" ] && [ "$pid" != "0" ]; do
        [ "$pid" = "$$" ] && return 0
        pid=$(ps -p "$pid" -o ppid= 2>/dev/null | tr -d ' ') || return 1
    done
    return 1
}

process_cwd_in_this_worktree() {
    local pid=$1
    local cwd
    cwd=$(lsof -a -p "$pid" -d cwd -Fn 2>/dev/null | sed -n 's/^n//p' | head -1) || true
    case "$cwd" in
        "$PWD"|"$PWD"/*) return 0 ;;
    esac
    return 1
}

kill_stale_tree() {
    local pid=$1
    for child in $(pgrep -P "$pid" 2>/dev/null); do
        kill_stale_tree "$child"
    done
    kill "$pid" 2>/dev/null || true
}

kill_stale_same_worktree_benchmark_stack() {
    $BENCHMARK_MODE || return 0

    local killed_any=false
    local pattern='scripts/run\.sh --benchmark|worker\.py|tsx.*src/server\.ts|node_modules/.bin/vite|ngrok http'
    for pid in $(pgrep -f "$pattern" 2>/dev/null); do
        [ "$pid" = "$$" ] && continue
        is_current_process_family "$pid" && continue

        local cmd
        cmd=$(ps -p "$pid" -o command= 2>/dev/null) || true
        if echo "$cmd" | grep -q "$PWD" || process_cwd_in_this_worktree "$pid"; then
            echo "🧹 Killing stale benchmark process from this worktree (PID $pid)"
            kill_stale_tree "$pid"
            killed_any=true
        fi
    done

    if $killed_any; then
        sleep 1
        for pid in $(pgrep -f "$pattern" 2>/dev/null); do
            [ "$pid" = "$$" ] && continue
            is_current_process_family "$pid" && continue
            if process_cwd_in_this_worktree "$pid"; then
                kill -9 "$pid" 2>/dev/null || true
            fi
        done
        echo "✅ Stale same-worktree benchmark processes stopped"
    fi
}

kill_stale_same_worktree_benchmark_stack

# ── Cloud instance: aggressive port cleanup ──
# On cloud there's exactly one worktree — no multi-workspace concern.
# Kill everything on our port range to prevent zombie conflicts from prior
# run.sh invocations or crashed services. Retry until every port is free.

if $IS_CLOUD; then
    CLOUD_PORTS=($BACKEND_PORT $FRONTEND_PORT $HEALTH_PORT $SDK_METRICS_PORT $NGROK_WEB_PORT)

    kill_port() {
        local port=$1
        if command -v fuser >/dev/null 2>&1; then
            fuser -k "$port/tcp" 2>/dev/null || true
        else
            for pid in $(lsof -ti :"$port" 2>/dev/null); do
                kill -9 "$pid" 2>/dev/null || true
            done
        fi
    }

    port_in_use() {
        local port=$1
        if command -v fuser >/dev/null 2>&1; then
            fuser "$port/tcp" >/dev/null 2>&1
        else
            lsof -ti :"$port" >/dev/null 2>&1
        fi
    }

    # Phase 1: kill everything on service ports + known process patterns
    CLOUD_KILLED=false
    for port in "${CLOUD_PORTS[@]}"; do
        if port_in_use "$port"; then
            echo "🧹 Killing processes on port $port"
            kill_port "$port"
            CLOUD_KILLED=true
        fi
    done
    for pattern in "worker\.py" "tsx.*server\.ts" "npx vite" "run_local_worker"; do
        for pid in $(pgrep -f "$pattern" 2>/dev/null); do
            echo "🧹 Killing $pattern (PID $pid)"
            kill -9 "$pid" 2>/dev/null || true
            CLOUD_KILLED=true
        done
    done

    # Phase 2: retry until all ports are free (processes may linger briefly)
    if $CLOUD_KILLED; then
        MAX_PORT_RETRIES=10
        for attempt in $(seq 1 $MAX_PORT_RETRIES); do
            sleep 1
            ALL_FREE=true
            for port in "${CLOUD_PORTS[@]}"; do
                if port_in_use "$port"; then
                    ALL_FREE=false
                    echo "   port $port still held (attempt $attempt/$MAX_PORT_RETRIES) — force-killing"
                    kill_port "$port"
                fi
            done
            if $ALL_FREE; then
                echo "✅ All ports free"
                break
            fi
            if [ "$attempt" -eq "$MAX_PORT_RETRIES" ]; then
                echo "❌ Ports still occupied after $MAX_PORT_RETRIES retries:"
                for port in "${CLOUD_PORTS[@]}"; do
                    port_in_use "$port" && echo "   port $port: $(fuser "$port/tcp" 2>&1 || lsof -ti :"$port" 2>/dev/null)"
                done
                exit 1
            fi
        done
    fi
fi

# ── Pre-flight: ensure Postgres is available ──
# Prefer Docker (per-workspace container), fall back to system Postgres when
# the Docker daemon isn't available (sandboxed containers, CI without --privileged).
DOCKER_OK=false
if docker_info_quick; then
    DOCKER_OK=true
fi

DB_CONTAINER="victoria-db-${CONDUCTOR_WORKSPACE_NAME}"
DB_VOLUME="victoria-pgdata-${CONDUCTOR_WORKSPACE_NAME}"
DB_OWNED_BY_US=false  # Track whether we started/created the DB (cleanup only stops what we own)
USE_SYSTEM_PG=false

if $DOCKER_OK; then
    # ── Docker path (macOS / Linux with working Docker) ──
    if ! docker ps &>/dev/null 2>&1; then
        if [ -d "/Applications/Docker.app" ]; then
            echo "🐳 Docker not running — starting Docker Desktop..."
            open -a Docker
            for i in $(seq 1 60); do
                if docker ps &>/dev/null 2>&1; then
                    echo "🐳 Docker is ready"
                    break
                fi
                if [ "$i" -eq 60 ]; then
                    echo "⚠️  Docker did not start in 60s — local Postgres may fail"
                fi
                sleep 1
            done
        fi
    fi

    LOCAL_DB_URL="postgresql://postgres:postgres@localhost:$LOCAL_DB_PORT/victoria"

    # Helper: create (or recreate) the Postgres container with the correct port
    create_db_container() {
        docker rm -f "$DB_CONTAINER" 2>/dev/null || true
        docker run -d \
            --name "$DB_CONTAINER" \
            -e POSTGRES_PASSWORD=postgres \
            -e POSTGRES_DB=victoria \
            -p "$LOCAL_DB_PORT:5432" \
            -v "$DB_VOLUME:/var/lib/postgresql/data" \
            postgres:16-alpine >/dev/null
    }

    if docker ps --filter "name=^${DB_CONTAINER}$" --format '{{.Names}}' | grep -q .; then
        ACTUAL_PORT=$(docker port "$DB_CONTAINER" 5432 2>/dev/null | head -1 | grep -o '[0-9]*$' || true)
        if [ "$ACTUAL_PORT" = "$LOCAL_DB_PORT" ]; then
            echo "🐘 Local Postgres already running ($DB_CONTAINER on port $LOCAL_DB_PORT)"
        else
            echo "🐘 Postgres container on wrong port ($ACTUAL_PORT vs $LOCAL_DB_PORT) — recreating..."
            create_db_container
            DB_OWNED_BY_US=true
        fi
    elif docker ps -a --filter "name=^${DB_CONTAINER}$" --format '{{.Names}}' | grep -q .; then
        ACTUAL_PORT=$(docker inspect "$DB_CONTAINER" --format='{{(index (index .HostConfig.PortBindings "5432/tcp") 0).HostPort}}' 2>/dev/null || true)
        if [ "$ACTUAL_PORT" = "$LOCAL_DB_PORT" ]; then
            echo "🐘 Starting stopped Postgres container..."
            docker start "$DB_CONTAINER" >/dev/null
            DB_OWNED_BY_US=true
        else
            echo "🐘 Stopped container on wrong port ($ACTUAL_PORT vs $LOCAL_DB_PORT) — recreating..."
            create_db_container
            DB_OWNED_BY_US=true
        fi
    else
        echo "🐘 Creating local Postgres container..."
        create_db_container
        DB_OWNED_BY_US=true
    fi

    # Wait for Postgres to accept connections
    echo -n "   Waiting for Postgres..."
    for i in $(seq 1 30); do
        if docker exec "$DB_CONTAINER" pg_isready -U postgres -q 2>/dev/null; then
            echo " ready (${i}s)"
            break
        fi
        if [ "$i" -eq 30 ]; then
            echo " ❌ timed out"
            exit 1
        fi
        sleep 1
    done
else
    # ── System Postgres fallback (no Docker) ──
    USE_SYSTEM_PG=true
    SYSTEM_PG_PORT=5432
    LOCAL_DB_URL="postgresql://postgres:postgres@localhost:$SYSTEM_PG_PORT/victoria"

    if pg_isready -h localhost -p "$SYSTEM_PG_PORT" -U postgres -q 2>/dev/null; then
        echo "🐘 System Postgres already running on port $SYSTEM_PG_PORT"
    else
        echo "🐘 Starting system Postgres..."
        PG_VER=$(pg_lsclusters -h 2>/dev/null | head -1 | awk '{print $1}')
        if [ -n "$PG_VER" ]; then
            pg_ctlcluster "$PG_VER" main start 2>/dev/null || service postgresql start 2>/dev/null || true
        else
            service postgresql start 2>/dev/null || true
        fi
        # Wait for it
        echo -n "   Waiting for Postgres..."
        for i in $(seq 1 30); do
            if pg_isready -h localhost -p "$SYSTEM_PG_PORT" -U postgres -q 2>/dev/null; then
                echo " ready (${i}s)"
                break
            fi
            if [ "$i" -eq 30 ]; then
                echo " ❌ No Docker and system Postgres failed to start."
                echo "   Run scripts/cloud-build.sh to install Postgres."
                exit 1
            fi
            sleep 1
        done
    fi
    # Ensure victoria DB exists (idempotent)
    PGPASSWORD=postgres psql -h localhost -U postgres -tc "SELECT 1 FROM pg_database WHERE datname='victoria'" 2>/dev/null \
        | grep -q 1 || PGPASSWORD=postgres createdb -h localhost -U postgres victoria 2>/dev/null || true
fi

# Fast Mode cache is intentionally shared across local/dev/prod so recorded runs
# survive local DB resets. Capture the prod DB URL from back-end/.env before this
# script overwrites DATABASE_URL with the local app database below.
if [ -z "${FAST_MODE_CACHE_DATABASE_URL:-}" ] && [ -f "back-end/.env" ]; then
    PROD_CACHE_DATABASE_URL=$(python3 - <<'PY'
from pathlib import Path

for raw in Path("back-end/.env").read_text().splitlines():
    line = raw.strip()
    if not line or line.startswith("#") or "=" not in line:
        continue
    key, value = line.split("=", 1)
    if key.strip() != "DATABASE_URL":
        continue
    value = value.strip()
    if (value.startswith('"') and value.endswith('"')) or (value.startswith("'") and value.endswith("'")):
        value = value[1:-1]
    print(value)
    break
PY
)
    if [ -n "$PROD_CACHE_DATABASE_URL" ]; then
        export FAST_MODE_CACHE_DATABASE_URL="$PROD_CACHE_DATABASE_URL"
    fi
fi
if [ -n "${FAST_MODE_CACHE_DATABASE_URL:-}" ]; then
    echo "🧠 Ensuring Fast Mode cache schema..."
    (cd back-end && npx tsx scripts/ensure-fast-mode-cache-schema.ts)
fi

# Larger Prisma pool: Fast Mode adds cache get/set on every LLM call, which under
# sub-agent fan-out competes with the agent's own writes for the connection pool
# (the known P2024 timeout signature). A bigger local pool absorbs the burst.
export DATABASE_URL="${LOCAL_DB_URL}?connection_limit=50&pool_timeout=30"
export DIRECT_URL="$LOCAL_DB_URL"

# Sync Prisma schema to local DB (idempotent, dev-only)
echo "🐘 Syncing Prisma schema..."
(cd back-end && npx prisma db push --skip-generate --accept-data-loss 2>&1 | tail -3)

# Seed local DB if dev user doesn't exist yet (full prod sync in scripts/setup-db.sh)
if $DOCKER_OK && ! $USE_SYSTEM_PG; then
    USER_EXISTS=$(docker exec "$DB_CONTAINER" psql -U postgres -d victoria -tAc \
      "SELECT COUNT(*) FROM \"User\" WHERE \"userId\" = '1f85ff25-6e29-4c1b-8739-f917bd101a30'" 2>/dev/null | tr -d ' ' || echo "0")
else
    USER_EXISTS=$(PGPASSWORD=postgres psql -h localhost -U postgres -d victoria -tAc \
      "SELECT COUNT(*) FROM \"User\" WHERE \"userId\" = '1f85ff25-6e29-4c1b-8739-f917bd101a30'" 2>/dev/null | tr -d ' ' || echo "0")
fi
if [ "$USER_EXISTS" = "0" ]; then
    echo "🌱 Syncing production data to local database (first run)..."
    (cd back-end && npx tsx scripts/seed-local.ts)
else
    echo "🌱 Local database already seeded; syncing browser credentials..."
    (cd back-end && npx tsx scripts/seed-local.ts --credentials-only)
fi

# ── Pre-flight: ensure node_modules exist for all JS services ──
JS_SVC_DIRS=(back-end front-end)
$IS_MAC && JS_SVC_DIRS+=(mac-app)
for svc_dir in "${JS_SVC_DIRS[@]}"; do
    if [ -f "$svc_dir/package.json" ] && [ ! -d "$svc_dir/node_modules" ]; then
        echo "📦 Installing $svc_dir dependencies..."
        (cd "$svc_dir" && npm install)
        echo "📦 $svc_dir deps ready"
    fi
done

# ── Pre-flight: ensure agents venv exists with deps installed ──
if [ ! -f agents/venv/bin/activate ] || ! agents/venv/bin/python -c "import temporalio" 2>/dev/null; then
    echo "🐍 Setting up agents virtualenv..."
    PYTHON_VERSION=$(cat agents/.python-version 2>/dev/null || echo "3.11")
    # Try asdf python first, then system python3
    PYTHON_BIN="$(asdf where python "$PYTHON_VERSION" 2>/dev/null)/bin/python3" || true
    if [ ! -x "$PYTHON_BIN" ]; then
        PYTHON_BIN=$(command -v python3)
    fi
    echo "   Using: $PYTHON_BIN ($($PYTHON_BIN --version 2>&1))"
    if [ ! -f agents/venv/bin/activate ]; then
        (cd agents && "$PYTHON_BIN" -m venv venv)
    fi
    (cd agents && source venv/bin/activate && pip install -r requirements.txt)
    echo "🐍 Agents venv ready"
fi

# Pre-flight: handle processes on our ports from this worktree.
# Cloud instances already handled above (aggressive cleanup). This block
# handles macOS multi-worktree scenarios where we must distinguish our
# processes from another workspace's.
if ! $IS_CLOUD; then
    SERVICE_PORTS=($BACKEND_PORT $FRONTEND_PORT $HEALTH_PORT $SDK_METRICS_PORT $NGROK_WEB_PORT)
    $IS_MAC && SERVICE_PORTS+=($MAC_APP_PORT)
    for port in "${SERVICE_PORTS[@]}"; do
        for pid in $(lsof -ti :"$port" 2>/dev/null); do
            cmd=$(ps -p "$pid" -o command= 2>/dev/null) || true
            echo "$cmd" | grep -qi docker && continue
            if process_belongs_to_this_worktree "$pid"; then
                continue
            fi
            echo "❌ Port $port in use by unknown process (PID $pid). Kill it manually or choose a different port range."
            exit 1
        done
    done
    echo "🧹 Cleaning stale services for this worktree before startup..."
    bash "$SCRIPT_DIR/kill-services.sh" || exit 1
fi

PIDS=()
NAMES=()
NGROK_PID=""
NGROK_CONFIG_FILE=""
SHUTTING_DOWN=false
SERVICE_STATUS=starting

dns_label_from_workspace() {
    python3 - <<'PY'
import os
import re
import sys

raw = os.environ.get("CONDUCTOR_WORKSPACE_NAME", "").strip()
if not raw:
    sys.exit("CONDUCTOR_WORKSPACE_NAME is required to derive a stable public domain")
label = re.sub(r"[^a-z0-9-]+", "-", raw.lower()).strip("-")
label = re.sub(r"-+", "-", label)
if not label:
    sys.exit(f"CONDUCTOR_WORKSPACE_NAME={raw!r} does not contain DNS-safe characters")
print(label[:50].strip("-"))
PY
}

ensure_ngrok_domain_reserved() {
    if [ -z "${NGROK_API_KEY:-}" ]; then
        return 0
    fi
    echo "🌐 Checking ngrok reserved domain $WORKTREE_DOMAIN"
    local domains_json
    domains_json=$(ngrok api reserved-domains list --api-key "$NGROK_API_KEY" --limit 1000 2>&1) || {
        echo "$domains_json"
        echo "❌ Could not list ngrok reserved domains with NGROK_API_KEY."
        exit 1
    }
    if printf '%s\n' "$domains_json" | grep -q "\"domain\"[[:space:]]*:[[:space:]]*\"$WORKTREE_DOMAIN\""; then
        echo "🌐 Reserved domain already exists: $WORKTREE_DOMAIN"
        return 0
    fi
    echo "🌐 Reserving ngrok domain $WORKTREE_DOMAIN"
    local create_output
    create_output=$(ngrok api reserved-domains create \
        --api-key "$NGROK_API_KEY" \
        --domain "$WORKTREE_DOMAIN" \
        --description "Conductor workspace $CONDUCTOR_WORKSPACE_NAME public frontend" 2>&1) || {
        echo "$create_output"
        echo "❌ Could not reserve $WORKTREE_DOMAIN. Confirm the ngrok account is on Pay-as-you-go and the domain is available."
        exit 1
    }
}

start_public_tunnel() {
    if ! command -v ngrok >/dev/null 2>&1; then
        echo "❌ ngrok is required for scripts/run.sh. Install it and configure an authtoken."
        exit 1
    fi
    ngrok config check >/dev/null 2>&1 || {
        echo "❌ ngrok config is invalid or missing an authtoken. Run: ngrok config add-authtoken <token>"
        exit 1
    }

    WORKSPACE_DNS_LABEL="$(dns_label_from_workspace)"
    NGROK_DOMAIN_SUFFIX="${NGROK_DOMAIN_SUFFIX:-ngrok.app}"
    WORKTREE_DOMAIN="${NGROK_WORKTREE_DOMAIN:-rose-${WORKSPACE_DNS_LABEL}.${NGROK_DOMAIN_SUFFIX}}"
    export WORKTREE_DOMAIN
    export PUBLIC_BASE_URL="https://$WORKTREE_DOMAIN"
    export VITE_ALLOWED_HOSTS="$WORKTREE_DOMAIN"
    export ALLOWED_ORIGINS="$ALLOWED_ORIGINS,$PUBLIC_BASE_URL"
    export NGROK_API_URL="http://127.0.0.1:$NGROK_WEB_PORT/api/tunnels"

    ensure_ngrok_domain_reserved

    mkdir -p .context
    local ngrok_base_config="$HOME/Library/Application Support/ngrok/ngrok.yml"
    if [ ! -f "$ngrok_base_config" ]; then
        ngrok_base_config="$HOME/.config/ngrok/ngrok.yml"
    fi
    if [ ! -f "$ngrok_base_config" ]; then
        echo "❌ Could not find the ngrok config file after ngrok config check succeeded."
        exit 1
    fi

    NGROK_CONFIG_FILE=".context/ngrok-${WORKSPACE_DNS_LABEL}.yml"
    cat > "$NGROK_CONFIG_FILE" <<EOF
version: "3"
agent:
  web_addr: 127.0.0.1:$NGROK_WEB_PORT
EOF

    echo "🌐 Starting public frontend tunnel: $PUBLIC_BASE_URL → localhost:$FRONTEND_PORT"
    ngrok http "$FRONTEND_PORT" \
        --config "$ngrok_base_config" \
        --config "$NGROK_CONFIG_FILE" \
        --domain "$WORKTREE_DOMAIN" \
        --log stdout \
        --log-format logfmt \
        --log-level info > .context/ngrok.log 2>&1 &
    NGROK_PID=$!
    PIDS+=($NGROK_PID); NAMES+=("ngrok")

    for attempt in $(seq 1 60); do
        if ! kill -0 "$NGROK_PID" 2>/dev/null; then
            echo "❌ ngrok exited before the public tunnel became ready."
            tail -60 .context/ngrok.log || true
            echo ""
            echo "Required ngrok billing state: Pay-as-you-go plan (\$20/month + usage) with reserved domain $WORKTREE_DOMAIN."
            echo "Checkout: https://dashboard.ngrok.com/billing/choose-a-plan"
            exit 1
        fi
        if curl -fsS "$NGROK_API_URL" >/tmp/rose-ngrok-tunnels.json 2>/dev/null; then
            if python3 - <<'PY'
import json
from pathlib import Path

data = json.loads(Path("/tmp/rose-ngrok-tunnels.json").read_text())
for tunnel in data.get("tunnels", []):
    if tunnel.get("proto") == "https" and tunnel.get("public_url"):
        raise SystemExit(0)
raise SystemExit(1)
PY
            then
                rm -f /tmp/rose-ngrok-tunnels.json
                echo "🌐 Public tunnel ready: $PUBLIC_BASE_URL"
                return 0
            fi
        fi
        sleep 1
    done

    echo "❌ ngrok tunnel did not become ready for $PUBLIC_BASE_URL → :$FRONTEND_PORT"
    echo "   ngrok API: $NGROK_API_URL"
    tail -80 .context/ngrok.log || true
    exit 1
}

write_services_manifest() {
    mkdir -p .context
    local names_csv pids_csv
    names_csv="$(IFS=,; echo "${NAMES[*]:-}")"
    pids_csv="$(IFS=,; echo "${PIDS[*]:-}")"
    SERVICE_NAMES="$names_csv" SERVICE_PIDS="$pids_csv" SERVICE_STATUS="$SERVICE_STATUS" \
        BENCHMARK_MODE="$BENCHMARK_MODE" DB_CONTAINER="$DB_CONTAINER" \
        DB_OWNED_BY_US="$DB_OWNED_BY_US" USE_SYSTEM_PG="$USE_SYSTEM_PG" \
        RUN_SH_PID="$$" python3 - <<'PY'
import json
import os
from datetime import datetime, timezone


def env_int(name: str, default: int = 0) -> int:
    try:
        return int(os.environ.get(name, default))
    except (TypeError, ValueError):
        return default


names = [part for part in os.environ.get("SERVICE_NAMES", "").split(",") if part]
pids_raw = [part for part in os.environ.get("SERVICE_PIDS", "").split(",") if part]
services = []
for index, name in enumerate(names):
    pid = env_int("__missing__", 0)
    if index < len(pids_raw):
        try:
            pid = int(pids_raw[index])
        except ValueError:
            pid = 0
    services.append({"name": name, "pid": pid})

root = os.getcwd()
data = {
    "schema_version": 1,
    "status": os.environ.get("SERVICE_STATUS", "unknown"),
    "generated_at": datetime.now(timezone.utc).isoformat(),
    "worktree": root,
    "run_sh_pid": env_int("RUN_SH_PID"),
    "benchmark_mode": os.environ.get("BENCHMARK_MODE", "false").lower() == "true",
    "ports": {
        "backend": env_int("BACKEND_PORT"),
        "frontend": env_int("FRONTEND_PORT"),
        "health": env_int("HEALTH_PORT"),
        "mac_app": env_int("MAC_APP_PORT"),
        "sdk_metrics": env_int("SDK_METRICS_PORT"),
        "local_db": env_int("LOCAL_DB_PORT"),
        "ngrok_api": env_int("NGROK_WEB_PORT"),
    },
    "urls": {
        "backend": os.environ.get("BACKEND_URL", ""),
        "backend_api": os.environ.get("BACKEND_API_URL", ""),
        "frontend": f"http://localhost:{os.environ.get('FRONTEND_PORT', '')}",
        "public": os.environ.get("PUBLIC_BASE_URL", ""),
        "health": f"http://localhost:{os.environ.get('HEALTH_PORT', '')}",
        "sdk_metrics": f"http://localhost:{os.environ.get('SDK_METRICS_PORT', '')}",
    },
    "temporal_task_queue": os.environ.get("TEMPORAL_TASK_QUEUE", ""),
    "database": {
        "container": os.environ.get("DB_CONTAINER", ""),
        "owned_by_run_sh": os.environ.get("DB_OWNED_BY_US", "false").lower() == "true",
        "use_system_postgres": os.environ.get("USE_SYSTEM_PG", "false").lower() == "true",
    },
    "env": {
        "benchmark_anon_steel_profile": os.environ.get("BENCHMARK_ANON_STEEL_PROFILE", "").lower() in ("1", "true", "yes", "on"),
        "benchmark_disable_saved_browser_auth": os.environ.get("BENCHMARK_DISABLE_SAVED_BROWSER_AUTH", "").lower() in ("1", "true", "yes", "on"),
    },
    "logs": {
        "backend": os.path.join(root, "back-end", "backend-logs.log"),
        "worker": os.path.join(root, "agents", "navi-worker-log.txt"),
    },
    "services": services,
}
tmp_path = os.path.join(root, ".context", "services.json.tmp")
path = os.path.join(root, ".context", "services.json")
with open(tmp_path, "w") as f:
    json.dump(data, f, indent=2, sort_keys=True)
    f.write("\n")
os.replace(tmp_path, path)
PY
}

kill_tree() {
    local pid=$1
    for child in $(pgrep -P "$pid" 2>/dev/null); do
        kill_tree "$child"
    done
    kill "$pid" 2>/dev/null || true
}

# SIGTERM the tree, wait briefly, then SIGKILL any survivors
kill_tree_hard() {
    local pid=$1
    kill_tree "$pid"
    sleep 1
    # Kill any survivors that ignored SIGTERM
    for child in $(pgrep -P "$pid" 2>/dev/null); do
        kill -9 "$child" 2>/dev/null || true
    done
    kill -9 "$pid" 2>/dev/null || true
}

cleanup() {
    if $SHUTTING_DOWN; then return; fi
    SHUTTING_DOWN=true
    echo "🛑 Stopping all services... (triggered by: $(caller 0 2>/dev/null || echo 'EXIT trap'), DB_OWNED_BY_US=$DB_OWNED_BY_US)"
    # Kill only the process trees we spawned (SIGTERM then SIGKILL)
    for pid in "${PIDS[@]}"; do
        kill_tree_hard "$pid"
    done
    # Sweep by manifest, cwd, and service ports in case a wrapper exited before
    # its child, or a descendant reparented during a cascade shutdown.
    bash "$SCRIPT_DIR/kill-services.sh" || true
    if $DB_OWNED_BY_US && ! $USE_SYSTEM_PG; then
        docker stop "$DB_CONTAINER" 2>/dev/null || true
    fi
    SERVICE_STATUS=stopped
    write_services_manifest || true
    [ -n "$NGROK_CONFIG_FILE" ] && rm -f "$NGROK_CONFIG_FILE"
    [ -n "$FAIL_DIR" ] && rm -rf "$FAIL_DIR"
    wait 2>/dev/null
}
trap cleanup EXIT

# Wrapper: run a service and write its exit code to a temp file on failure
FAIL_DIR=$(mktemp -d)
run_service() {
    local name="$1"
    shift
    "$@"
    local code=$?
    if [ $code -ne 0 ]; then
        echo "$name" > "$FAIL_DIR/failed"
        echo "$code" > "$FAIL_DIR/exit_code"
    fi
    return $code
}

# Public URL flow:
#   CONDUCTOR_WORKSPACE_NAME -> rose-<workspace>.<suffix>
#   ngrok reserved domain -> Vite dev server on FRONTEND_PORT
#   backend exposes PUBLIC_BASE_URL for /api/test-payment/public-url
start_public_tunnel
export FAST_MODE_ANTHROPIC_PROXY_URL="$PUBLIC_BASE_URL/anthropic-proxy"
export FAST_MODE_CODEX_PROXY_URL="$PUBLIC_BASE_URL/codex-proxy"

# Launch each service
if $BENCHMARK_MODE; then
    # In benchmark mode, use plain tsx (no watch) to prevent file-change restarts from killing the backend mid-run
    run_service "back-end" bash -c 'set -eo pipefail; cd back-end && rm -f backend-logs.log && PORT=$BACKEND_PORT npx tsx src/server.ts 2>&1 | tee backend-logs.log' &
else
    run_service "back-end" bash -c 'set -eo pipefail; cd back-end && rm -f backend-logs.log && PORT=$BACKEND_PORT npx tsx watch src/server.ts 2>&1 | tee backend-logs.log' &
fi
PIDS+=($!); NAMES+=("back-end")

# Front-end is always launched — benchmark mode needs it for semantic tests
# (Chrome CDP drives a real browser against the dev server in parallel with smoke).
run_service "front-end" bash -c 'set -eo pipefail; cd front-end && rm -f frontend-logs.log && VITE_DEV_PORT=$FRONTEND_PORT npx vite 2>&1 | tee frontend-logs.log' &
PIDS+=($!); NAMES+=("front-end")

# mac-app is skipped in benchmark mode (Electron is heavy and smoke doesn't touch it).
if ! $BENCHMARK_MODE && $IS_MAC; then
    run_service "mac-app" bash -c 'set -eo pipefail; cd mac-app && source ~/.nvm/nvm.sh && nvm use 20.10.0 && rm -f mac-app-console-logs.log mac-app-ipc-logs.log && VITE_BACKEND_API_URL=http://localhost:$BACKEND_PORT npm run dev 2>&1 | tee mac-app-console-logs.log' &
    PIDS+=($!); NAMES+=("mac-app")
fi

run_service "agents" bash -c 'set -eo pipefail; cd agents && source venv/bin/activate && HEALTH_CHECK_PORT=$HEALTH_PORT SDK_METRICS_PORT=$SDK_METRICS_PORT ./scripts/run_local_worker.sh' &
PIDS+=($!); NAMES+=("agents")

SERVICE_STATUS=running
write_services_manifest
echo "🧭 Service manifest: .context/services.json"
echo "🌐 Public frontend: $PUBLIC_BASE_URL"

echo "⏳ Verifying public tunnel smoke..."
bash scripts/test-public-tunnel.sh

# ── Post-launch: verify exactly one listener per service port ──
# Wait for services to bind, then confirm no duplicate listeners.
# Only the backend port is checked (the critical one for API calls); the
# agents worker binds to SDK_METRICS_PORT which may race with health.
if $IS_CLOUD; then
    echo -n "⏳ Verifying port bindings..."
    VERIFY_RETRIES=15
    for attempt in $(seq 1 $VERIFY_RETRIES); do
        sleep 2
        BACKEND_READY=false
        if python3 -c "import socket; s=socket.socket(); s.settimeout(1); exit(0 if s.connect_ex(('127.0.0.1',$BACKEND_PORT))==0 else 1); s.close()" 2>/dev/null; then
            BACKEND_READY=true
        fi
        WORKER_READY=false
        if python3 -c "import socket; s=socket.socket(); s.settimeout(1); exit(0 if s.connect_ex(('127.0.0.1',$SDK_METRICS_PORT))==0 else 1); s.close()" 2>/dev/null; then
            WORKER_READY=true
        fi
        if $BACKEND_READY && $WORKER_READY; then
            echo " backend=$BACKEND_PORT ✓  worker=$SDK_METRICS_PORT ✓"
            break
        fi
        if [ "$attempt" -eq "$VERIFY_RETRIES" ]; then
            echo ""
            $BACKEND_READY || echo "   ❌ Backend not listening on $BACKEND_PORT"
            $WORKER_READY  || echo "   ❌ Worker not listening on $SDK_METRICS_PORT"
            echo "   Continuing anyway — services may still be starting"
        fi
    done
fi

# Poll for failed children every second
while true; do
    if $SHUTTING_DOWN; then break; fi

    # Check if any process has died
    for i in "${!PIDS[@]}"; do
        pid="${PIDS[$i]}"
        if ! kill -0 "$pid" 2>/dev/null; then
            # Process is gone — get its exit code
            wait "$pid" 2>/dev/null
            code=$?
            name="${NAMES[$i]}"
            if [ $code -ne 0 ]; then
                echo ""
                echo "❌ $name (PID $pid) exited with code $code — shutting down all services."
                # Log which services are still alive for traceability
                for j in "${!PIDS[@]}"; do
                    other_pid="${PIDS[$j]}"
                    other_name="${NAMES[$j]}"
                    if [ "$j" != "$i" ] && [ -n "$other_pid" ]; then
                        if kill -0 "$other_pid" 2>/dev/null; then
                            echo "   ├── $other_name (PID $other_pid): still running — will be killed"
                        else
                            wait "$other_pid" 2>/dev/null; other_code=$?
                            echo "   ├── $other_name (PID $other_pid): already dead (code $other_code)"
                        fi
                    fi
                done
                cleanup
                rm -rf "$FAIL_DIR"
                exit $code
            fi
            # Exited with code 0 — log it and remove from tracking
            echo "⚠️  $name (PID $pid) exited with code 0 (unexpected for a long-running service)"
            unset "PIDS[$i]"
            unset "NAMES[$i]"
        fi
    done

    # If all children are gone, exit
    remaining=0
    for pid in "${PIDS[@]}"; do
        if [ -n "$pid" ]; then remaining=1; break; fi
    done
    if [ $remaining -eq 0 ]; then
        echo "⚠️  All services exited (code 0) — nothing left to monitor. Shutting down."
        break
    fi

    sleep 1
done

rm -rf "$FAIL_DIR"
